const now = new Date();
return [{
  json: {
    config: {
      dry_run: true,
      emergency_stop: false,
      timezone: 'Europe/London',
      calling_window_start_hour: 9,
      calling_window_end_hour: 17,
      daily_cap: 20,
      batch_size: 1,
      rate_limit_seconds: 3,
      approved_contacts_url: 'https://replace.example/api/approved-callable-contacts',
      vapi_base_url: 'https://api.vapi.ai',
      vapi_assistant_id: '',
      vapi_phone_number_id: '',
      analysis_webhook_url: 'https://replace.example/webhook/javedai-vapi-post-call',
      analysis_forwarding_enabled: true,
      campaign_ref: 'javedai-portfolio-safe-demo'
    },
    triggered_at: now.toISOString()
  }
}];

const config = $input.first().json.config;
return [{
  json: {
    config,
    contact_ref: 'fictional-demo-contact',
    phone: '+447700900000',
    hubspot_contact_id: '',
    status: 'approved',
    outreach_permitted: true,
    consent_to_call: true,
    suppressed: false,
    do_not_call: false,
    timezone: 'Europe/London',
    daily_call_count: 0,
    source: 'built-in-dry-run-fixture'
  }
}];

const config = $node['Build Safe Configuration'].json.config;
const rawItems = $input.all().map((item) => item.json ?? {});
const contacts = [];
for (const raw of rawItems) {
  if (Array.isArray(raw)) contacts.push(...raw);
  else if (Array.isArray(raw.results)) contacts.push(...raw.results);
  else if (Array.isArray(raw.contacts)) contacts.push(...raw.contacts);
  else if (raw.contact_ref || raw.contact_id || raw.phone || raw.phone_number) contacts.push(raw);
}
if (contacts.length === 0) {
  return [{ json: { config, no_contact: true, source: 'empty-contact-feed' } }];
}
return contacts.map((contact) => ({
  json: {
    config,
    contact_ref: String(contact.contact_ref ?? contact.contact_id ?? contact.id ?? ''),
    phone: String(contact.phone ?? contact.phone_number ?? ''),
    hubspot_contact_id: String(contact.hubspot_contact_id ?? ''),
    status: String(contact.status ?? '').toLowerCase(),
    outreach_permitted: contact.outreach_permitted === true,
    consent_to_call: contact.consent_to_call === true,
    suppressed: contact.suppressed === true,
    do_not_call: contact.do_not_call === true,
    timezone: String(contact.timezone ?? 'Europe/London'),
    daily_call_count: Number(contact.daily_call_count ?? 0),
    next_call_at: contact.next_call_at ?? null,
    source: String(contact.source ?? 'approved-contact-source')
  }
}));

const workflowState = $getWorkflowStaticData('global');
workflowState.outboundDailyReservations ??= {};
workflowState.outboundIdempotency ??= {};
const stableHash = (value) => {
  let hash = 2166136261;
  for (const character of String(value)) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
};
const output = [];
for (const item of $input.all()) {
  const data = item.json;
  const config = data.config;
  const now = new Date();
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-GB', {
    timeZone: config.timezone, weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', hourCycle: 'h23'
  }).formatToParts(now).filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
  const dayKey = `${parts.year}-${parts.month}-${parts.day}`;
  const weekdayAllowed = !['Sat', 'Sun'].includes(parts.weekday);
  const localHour = Number(parts.hour);
  const insideWindow = weekdayAllowed && localHour >= config.calling_window_start_hour && localHour < config.calling_window_end_hour;
  const reasons = [];
  const phone = String(data.phone ?? '').replace(/[\s().-]/g, '');
  if (data.no_contact) reasons.push('no-approved-contacts-returned');
  if (config.emergency_stop) reasons.push('emergency-stop-enabled');
  if (!['approved', 'call-approved'].includes(data.status)) reasons.push('contact-not-explicitly-approved');
  if (!data.outreach_permitted) reasons.push('outreach-not-permitted');
  if (!data.consent_to_call) reasons.push('call-consent-not-recorded');
  if (data.suppressed || data.do_not_call) reasons.push('suppressed-or-do-not-call');
  if (data.timezone !== config.timezone) reasons.push('timezone-not-approved-for-this-campaign');
  if (!/^\+44\d{9,10}$/.test(phone)) reasons.push('invalid-or-non-uk-e164-number');
  if (data.next_call_at && new Date(data.next_call_at).getTime() > now.getTime()) reasons.push('scheduled-for-later');
  if (!config.dry_run && !insideWindow) reasons.push('outside-uk-weekday-calling-window');
  const contactKey = data.contact_ref || stableHash(phone);
  const idempotencyKey = `${config.campaign_ref}:${dayKey}:${contactKey}`;
  if (workflowState.outboundIdempotency[idempotencyKey]) reasons.push('already-reserved-today');
  let reservedCount = Math.max(Number(workflowState.outboundDailyReservations[dayKey] ?? 0), Number(data.daily_call_count ?? 0));
  if (!config.dry_run && reservedCount >= config.daily_cap) reasons.push('daily-cap-reached');
  const route = reasons.length === 0 ? 'call' : 'skip';
  if (route === 'call' && !config.dry_run) {
    workflowState.outboundIdempotency[idempotencyKey] = now.toISOString();
    reservedCount += 1;
    workflowState.outboundDailyReservations[dayKey] = reservedCount;
  }
  output.push({ json: {
    ...data,
    phone,
    phone_hash: stableHash(phone),
    idempotency_key: idempotencyKey,
    route,
    safety_reasons: reasons,
    uk_local_day: parts.weekday,
    uk_local_hour: localHour,
    inside_calling_window: insideWindow,
    reserved_daily_count: reservedCount,
    checked_at: now.toISOString()
  }});
}
return output;

const state = $getWorkflowStaticData('global');
state.outboundAudit ??= [];
state.outboundAudit.push({
  at: new Date().toISOString(),
  event: 'call-skipped',
  contact_ref: $json.contact_ref || null,
  phone_hash: $json.phone_hash || null,
  reasons: $json.safety_reasons || []
});
state.outboundAudit = state.outboundAudit.slice(-500);
return [{ json: { status: 'skipped', contact_ref: $json.contact_ref || null, reasons: $json.safety_reasons || [] } }];

const data = $json;
const config = data.config;
const missingConfiguration = !config.dry_run && (!config.vapi_assistant_id || !config.vapi_phone_number_id);
if (missingConfiguration) {
  return [{ json: { ...data, call_route: 'dry-run', safety_reasons: [...(data.safety_reasons || []), 'vapi-ids-not-configured-preview-only'] } }];
}
const vapiRequest = {
  assistantId: config.vapi_assistant_id,
  phoneNumberId: config.vapi_phone_number_id,
  customer: { number: data.phone },
  name: config.campaign_ref.slice(0, 40),
  assistantOverrides: {
    variableValues: {
      contact_ref: data.contact_ref,
      hubspot_contact_id: data.hubspot_contact_id || '',
      campaign_ref: config.campaign_ref,
      idempotency_key: data.idempotency_key
    }
  }
};
return [{ json: { ...data, call_route: config.dry_run ? 'dry-run' : 'live', vapi_request: vapiRequest } }];

const masked = $json.phone ? `${$json.phone.slice(0, 4)}…${$json.phone.slice(-3)}` : null;
return [{ json: {
  status: 'dry-run-preview',
  contact_ref: $json.contact_ref,
  masked_phone: masked,
  phone_hash: $json.phone_hash,
  idempotency_key: $json.idempotency_key,
  would_post_to: `${$json.config.vapi_base_url}/call`,
  safety_checks_passed: true,
  generated_at: new Date().toISOString()
} }];

const state = $getWorkflowStaticData('global');
state.outboundAudit ??= [];
state.outboundAudit.push({ at: new Date().toISOString(), event: 'dry-run-preview', contact_ref: $json.contact_ref, phone_hash: $json.phone_hash });
state.outboundAudit = state.outboundAudit.slice(-500);
return [{ json: $json }];

const response = $json ?? {};
const requestContext = $node['Prepare Minimal Vapi Call Request'].json;
const callId = String(response.id ?? response.call?.id ?? '');
return [{ json: {
  config: requestContext.config,
  contact_ref: requestContext.contact_ref,
  hubspot_contact_id: requestContext.hubspot_contact_id,
  phone_hash: requestContext.phone_hash,
  idempotency_key: requestContext.idempotency_key,
  call_id: callId,
  call_status: String(response.status ?? (callId ? 'queued' : 'creation-failed')),
  call_created: Boolean(callId),
  created_at: new Date().toISOString(),
  api_error: response.error?.message ?? response.message ?? null
} }];

const state = $getWorkflowStaticData('global');
state.outboundAudit ??= [];
state.outboundAudit.push({
  at: new Date().toISOString(),
  event: $json.call_created ? 'vapi-call-created' : 'vapi-call-creation-failed',
  call_id: $json.call_id || null,
  contact_ref: $json.contact_ref || null,
  phone_hash: $json.phone_hash || null,
  status: $json.call_status
});
state.outboundAudit = state.outboundAudit.slice(-500);
return [{ json: { ...$json, creation_route: $json.call_created ? 'created' : 'failed' } }];

const response = $json ?? {};
const creation = $node['Persist Call Creation Audit'].json;
const artifact = response.artifact ?? {};
const status = String(response.status ?? creation.call_status ?? 'unknown');
const endedReason = String(response.endedReason ?? response.ended_reason ?? '');
const isFinal = status === 'ended' || Boolean(response.endedAt) || Boolean(endedReason);
return [{ json: {
  event_type: 'outbound-status-poll',
  call_id: creation.call_id,
  call_status: status,
  ended_reason: endedReason || null,
  started_at: response.startedAt ?? null,
  ended_at: response.endedAt ?? null,
  duration_seconds: Number(response.durationSeconds ?? 0),
  transcript: artifact.transcript ?? null,
  messages: Array.isArray(artifact.messages) ? artifact.messages : [],
  recording_present: Boolean(artifact.recording),
  contact_ref: creation.contact_ref,
  hubspot_contact_id: creation.hubspot_contact_id,
  phone_hash: creation.phone_hash,
  idempotency_key: creation.idempotency_key,
  config: creation.config,
  final_route: isFinal ? 'final' : 'await-webhook',
  observed_at: new Date().toISOString()
} }];

const snapshot = $node['Normalize Post Call Snapshot'].json;
const state = $getWorkflowStaticData('global');
state.outboundAudit ??= [];
state.outboundAudit.push({
  at: new Date().toISOString(),
  event: 'final-call-forward-attempted',
  call_id: snapshot.call_id,
  contact_ref: snapshot.contact_ref || null,
  phone_hash: snapshot.phone_hash || null,
  status: snapshot.call_status,
  ended_reason: snapshot.ended_reason
});
state.outboundAudit = state.outboundAudit.slice(-500);
return [{ json: { call_id: snapshot.call_id, status: snapshot.call_status, analysis_forward_attempted: true } }];

const state = $getWorkflowStaticData('global');
state.outboundAudit ??= [];
state.outboundAudit.push({
  at: new Date().toISOString(),
  event: 'awaiting-vapi-end-of-call-webhook',
  call_id: $json.call_id,
  contact_ref: $json.contact_ref || null,
  phone_hash: $json.phone_hash || null,
  status: $json.call_status
});
state.outboundAudit = state.outboundAudit.slice(-500);
return [{ json: { call_id: $json.call_id, status: $json.call_status, awaiting_webhook: true } }];
